@Test
public void testFilterWithNegativeAndNegative_2_oe() {
    final byte[] byteArray = ImagingConstants.EMPTY_BYTE_ARRAY;
    final TransparencyFilterIndexedColor transparencyFilterIndexedColor = new TransparencyFilterIndexedColor(byteArray);
    try {
        transparencyFilterIndexedColor.filter((-416), (-398));
    } catch(final Exception e) {
        assertEquals("TransparencyFilterIndexedColor index: -398, bytes.length: 0",e.getMessage());
}
}

mut_method_definition:
@Override
    public int filter(final int rgb, final int index) throws ImageReadException, IOException {
        final int length = getLength();
        if (index >= length) { // TODO see below - is this check correct?
            return rgb;
        }

        if ((index < 0) || (index > length)) { // TODO check for > length cannot be true because of check above
            throw new ImageReadException(
                    "TransparencyFilterIndexedColor index: " + index + ", bytes.length: " + length);
        }

        final int alpha = getByte(index);
        return ((0xff & alpha) << 24) | (0x00ffffff & rgb);
    }

