@Test
public void testConvertValidDisposalMethodValues_1_oe() throws ImageReadException {
    final DisposalMethod unspecified = GifImageParser.createDisposalMethodFromIntValue(0);
    GifImageParser.createDisposalMethodFromIntValue(1);
    GifImageParser.createDisposalMethodFromIntValue(2);
    GifImageParser.createDisposalMethodFromIntValue(3);
    GifImageParser.createDisposalMethodFromIntValue(4);
    GifImageParser.createDisposalMethodFromIntValue(5);
    GifImageParser.createDisposalMethodFromIntValue(6);
    GifImageParser.createDisposalMethodFromIntValue(7);
    Assertions.assertEquals(unspecified, DisposalMethod.UNSPECIFIED);
}

mut_method_definition:
static DisposalMethod createDisposalMethodFromIntValue(final int value) throws ImageReadException {
        switch (value) {
            case 0:
                return DisposalMethod.UNSPECIFIED;
            case 1:
                return DisposalMethod.DO_NOT_DISPOSE;
            case 2:
                return DisposalMethod.RESTORE_TO_BACKGROUND;
            case 3:
                return DisposalMethod.RESTORE_TO_PREVIOUS;
            case 4:
                return DisposalMethod.TO_BE_DEFINED_1;
            case 5:
                return DisposalMethod.TO_BE_DEFINED_2;
            case 6:
                return DisposalMethod.TO_BE_DEFINED_3;
            case 7:
                return DisposalMethod.TO_BE_DEFINED_4;
            default:
                throw new ImageReadException("GIF: Invalid parsing of disposal method");
        }
    }

